// Generated by zfa — standalone MCP server entrypoint for mcp_demo.
//
// Run via:
//   dart run bin/mcp_server.dart            # stdio (default)
//   dart run bin/mcp_server.dart --sse      # SSE on :8372
//   dart run bin/mcp_server.dart --list-tools
library;

import 'dart:convert';
import 'dart:io';

import 'package:zuraffa/zuraffa.dart';
import 'package:mcp_demo/src/mcp/tools.dart';

Future<void> main(List<String> args) async {
  final useSse = args.contains('--sse');
  final listToolsOnly = args.contains('--list-tools');
  final ssePort = _intArg(args, '--port', 8372);
  final authToken = _strArg(args, '--token');

  final mcp = McpServerPlugin(tools: mcpTools);
  final engine = ZuraffaEngine()..register(mcp);
  await engine.bootstrap();

  if (listToolsOnly) {
    final tools = mcp
        .listTools()
        .map(
          (t) => {
            'name': t.name,
            'description': t.description,
            'inputSchema': t.inputSchema,
          },
        )
        .toList();
    print(jsonEncode({'tools': tools}));
    return;
  }

  if (useSse) {
    if (authToken == null || authToken.isEmpty) {
      stderr.writeln(
        '❌ SSE mode requires a nonempty --token for authentication.',
      );
      stderr.writeln(
        '   Usage: dart run bin/mcp_server.dart --sse --token <token>',
      );
      exit(1);
    }
    await mcp.serveSse(port: ssePort, authToken: authToken);
  } else {
    await mcp.serveStdio();
  }
}

int _intArg(List<String> args, String name, int defaultValue) {
  final i = args.indexOf(name);
  if (i == -1 || i + 1 >= args.length) return defaultValue;
  return int.tryParse(args[i + 1]) ?? defaultValue;
}

String? _strArg(List<String> args, String name) {
  final i = args.indexOf(name);
  if (i == -1 || i + 1 >= args.length) return null;
  return args[i + 1];
}
